/// <summary>
/// N.Freidenberger 13.02.2025
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args            _args)
{
    Dialog              dialog = new Dialog();
    DialogField         dlgTableName;
    TableName   tableName;
    dlgTableName = dialog.addField(extendedTypeStr(TableName));
    DictTable dt; 
    fieldId   recIdfId, dataAreaIdfId;



    if (dialog.run())
    {
        tableName = dlgTableName.value();
        if (tableName)
        {
            dt = new DictTable(tableName2Id(tableName));
            if (dt)
            {
                recIdfId = dt.fieldName2Id('RecId');
                dataAreaIdfId = dt.fieldName2Id('DataAreaId');
                Query      query = new Query();

                QueryBuildDataSource  tableDS = query.addDataSource(tableName2Id(tableName));
                query.allowCrossCompany (true);
                tableDS.addGroupByField(dataAreaIdfId);
                tableDS.addSelectionField(recIdfId,SelectionField::Count);

                QueryRun    queryRun = new  QueryRun(query);
                while (queryRun.next())
                {
                    Common  tableCommon = queryRun.get(tableName2Id(tableName));

                    info(strFmt("@NDX:NXACountRecInTable",tableName,tableCommon.DataAreaId,tableCommon.RecId)) ;
                }
            }
        }
    }
}
